// WHERE A PERSON'S PACK LIVES, and whether this session may go and get it. Two questions,
// one module, because three readers have to answer them identically: the step that copies
// the pack in, the step that explains why nothing was copied, and the conformance rules that
// judge a store this repo holds.
//
// THE ADDRESS, from this pack's own entry in `.claudinite-settings.json`:
//
//   { "id": "claude-code-web-users-support", "config": { "repo": "owner/name", "path": "preferences" } }
//
// `repo` is required, because what a person carries belongs to them rather than to any one
// project, and a repository is the smallest thing that can hold it for a whole fleet without
// living inside any member of it. `path` is where the people sit in that repository and
// defaults to `preferences`. One directory per person, named for their exact identity:
// `<path>/<email>/`, an ordinary pack directory.
//
// THE PERMISSION is a separate question with the same answer shape. A session that has no
// identity, no store, or no person watching has nowhere to copy from and no one to copy for,
// and every reader needs the same list of reasons: one to stop, the other to say why.
//
// Dependency-free and pure. The caller supplies the parsed config and the environment, so
// this module touches neither disk nor network and is testable standalone.

export const DEFAULT_PATH = 'preferences';

// `{ repo, path }` when the config names a usable store, else null. Null covers both
// "nothing declared" and "declared but unusable" deliberately: every caller's next move is
// the same either way, and the difference is reported once, by the rule that exists to
// report it.
export function resolveStore(config) {
  if (config === null || typeof config !== 'object' || Array.isArray(config)) return null;
  if (typeof config.repo !== 'string' || !/^[^/\s]+\/[^/\s]+$/.test(config.repo)) return null;
  if (config.path !== undefined && (typeof config.path !== 'string' || config.path.includes('..') || config.path.startsWith('/'))) return null;
  const path = (config.path ?? DEFAULT_PATH).replace(/^\.\/+|\/+$/g, '');
  return { repo: config.repo, path: path || DEFAULT_PATH };
}

// Where one person's pack sits inside the store, as a repo-relative directory path. An
// address only: whether it is read from a working tree or cloned is the caller's business.
export function packDirFor(store, email) {
  return `${store.path}/${email}`;
}

// Is this string usable as the name of a person's pack? It becomes a path segment and an
// argument to git, so an implausible one is refused rather than traversed with: `../../x` as
// an "email" would address an arbitrary directory.
export const isUsableIdentity = (email) => typeof email === 'string'
  && /^[^\s/\\]+@[^\s/\\]+$/.test(email)
  && !email.includes('..');

// Why this session gets no personal pack, in the reader's own words, or null when it should
// get one. Pure, so the step that says this and the step that acts on it cannot disagree,
// and so the saying costs no second look at the world.
//
// Attendedness is one of the reasons: a routine fired under a person's account carries their
// identity but not their presence, and a pack written for a present person (a popup for every
// decision, a callout closing every turn) misdirects a run nobody is watching. Only an
// explicit "not attended" declines, so an older harness that sets nothing still copies.
export function declineReason(config, env) {
  const tidy = (s) => String(s).replace(/["\\]/g, '');
  if (!resolveStore(config)) {
    return 'this project declares no store for personal packs (the pack entry\'s "config": { "repo": … })';
  }
  if (env.CLAUDE_CODE_SESSION_ATTENDED === '0') {
    return 'the session is unattended (CLAUDE_CODE_SESSION_ATTENDED=0) and a personal pack is for a present person';
  }
  const email = env.CLAUDE_CODE_USER_EMAIL || '';
  if (!email) return 'CLAUDE_CODE_USER_EMAIL is not set';
  if (!isUsableIdentity(email)) return `CLAUDE_CODE_USER_EMAIL (${tidy(email)}) is not a usable directory name`;
  return null;
}
// Copy the pack belonging to the person in front of this session out of the store and into
// this repository's session pack root, where the engine's loader finds it.
//
// WHY A WHOLE PACK AND NOT A FILE. What a person wants a session to know is not only prose.
// It is a skill they reach for, a check that catches the mistake they keep making, a
// requirement their tooling needs installed. Every one of those already has a carrier, the
// pack, with an engine that mounts, runs and reports it. Copying a pack gets all of them at
// once; a preferences file could only ever carry the first.
//
// IT WRITES INTO `.claudinite/temp/packs/current_user/` and reports nothing. The directory is
// the whole interface: the loader reads it, `session-start.mjs` reads it to say what landed,
// and a session that failed to copy leaves the same directory holding the placeholder. There
// is no status file, because everything a reader needs is either in the directory or is a
// pure function of the config and the environment (user_pack_address.mjs's `declineReason`).
//
// LOCAL FIRST. When this tree IS the store, the working copy is what the owner is reading and
// editing, and a clone would serve the default branch and quietly hide the edit in progress.
//
// FAIL-SOFT THROUGHOUT. No identity, no configured store, no directory for this person, a
// clone that fails: the placeholder stays and the session proceeds on default interaction
// behaviour. Nothing here is load-bearing, since the packs, checks and skills a session needs
// are already local.
//
// WHAT IT WILL WRITE, and nothing else: Markdown, JavaScript modules and JSON, under one
// directory, within a file count and byte budget. A pack is executable code that will run
// inside this session's hooks, so the store repository is as trusted as this one; that is
// stated in the pack's README, because no cap here can substitute for it.

import { existsSync, mkdirSync, readFileSync, writeFileSync, readdirSync, statSync, mkdtempSync } from 'node:fs';
import { join, dirname, relative, sep } from 'node:path';
import { tmpdir } from 'node:os';
import { spawnSync } from 'node:child_process';
import { removeTree } from '../../engine/remove-tree.mjs';
import { resolveStore, packDirFor, declineReason } from './user_pack_address.mjs';

const CLONE_TIMEOUT_MS = 60_000;

// The budget a person's pack is copied within. Generous for what a pack is, small enough that
// a mistake in the store cannot fill a session's disk or its context.
const MAX_FILES = 60;
const MAX_BYTES = 512 * 1024;
const COPYABLE = /\.(md|mjs|json)$/;

// Where the copy lands. The engine owns the name (engine/pack_loader/pack-registry.mjs); it is
// spelled here rather than imported because a member's vendored engine may predate the
// constant, and a step that fails to import is a step that never ran.
const PACK_DIR = join('.claudinite', 'temp', 'packs', 'current_user');

// The session root ignores itself. A member's own .gitignore may say nothing about it, and a
// self-ignoring file reaches every member on its next session with no edit of theirs.
const SESSION_ROOT_GITIGNORE = `# GENERATED by claude-code-web-users-support: session state, copied in every session
# start. Not tracked.
*
`;

export const packDirIn = (root) => join(root, PACK_DIR);
export const proseIn = (root) => join(packDirIn(root), 'RULES.md');

// What the prose file says when no pack was copied. It is written rather than left absent
// because the rules index imports that path literally in every session of a repo with this
// feature, and an import with no file behind it has no defined behaviour on the memory
// channel and no way to report one. Its exact text is how `session-start.mjs` tells "nothing
// landed" from "here are your rules".
export const PLACEHOLDER = '<!-- No personal pack was copied into this session. -->\n';

// The manifest the copied pack runs under when the person's own directory carries none, which
// is the ordinary case: someone with rules to state should not have to write a manifest to
// state them. Their own `pack.mjs` is copied untouched when they have one, and it must set
// neither `id`, which the engine takes from the directory and this directory is the session's,
// nor `version`, which a pack distributed to nobody has nothing to hold.
const SYNTHESIZED_MANIFEST = `// GENERATED by claude-code-web-users-support: the manifest the person's own pack
// directory did not carry. Edit nothing here, it is rewritten every session.
export default {
  ruleRoutingGuidance: {
    belongs: 'how this person wants to be worked with, in every project they work in',
    excludes: 'a project\\'s own conventions, which belong to the packs that own each subject',
  },
};
`;

// Every file under a directory in this tree, as paths relative to it.
function treeFiles(absDir, prefix = '') {
  const out = [];
  for (const entry of readdirSync(absDir, { withFileTypes: true })) {
    if (entry.name === '.git') continue;
    const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isDirectory()) out.push(...treeFiles(join(absDir, entry.name), rel));
    else if (entry.isFile()) out.push(rel);
  }
  return out;
}

// One git call, with its own clock, reporting the line git ended on.
function git(args, cwd) {
  const run = spawnSync('git', args, { cwd, encoding: 'utf8', timeout: CLONE_TIMEOUT_MS });
  if (run.error?.code === 'ETIMEDOUT') throw new Error(`git ${args[0]} did not finish in ${Math.round(CLONE_TIMEOUT_MS / 1000)}s`);
  if (run.status !== 0) throw new Error((run.stderr || `git ${args[0]} exited ${run.status}`).trim().split('\n').pop());
}

// The store's default branch with only this person's directory checked out, in a directory the
// caller removes. A CLONE and not a download: this repository's own experience is that codeload
// and the repo-scoped API are both denied by the sandbox proxy where git against the same
// repository is not, and a private store is reachable at all only through the credentials git
// is already configured with. Shallow and blob-filtered, so what it costs is one person's
// directory rather than the store's history.
function checkout(store, packDir) {
  const dir = mkdtempSync(join(tmpdir(), 'claudinite-personal-pack-'));
  git(['clone', '--depth', '1', '--filter=blob:none', '--sparse',
    process.env.CLAUDINITE_USER_PACKS_CLONE_URL || `https://github.com/${store.repo}`, dir]);
  git(['sparse-checkout', 'set', '--no-cone', packDir], dir);
  return dir;
}

// Leave the directory holding nothing but the placeholder: what every miss converges on, and
// what the very first session in a container starts from.
function leavePlaceholder(dest) {
  try {
    mkdirSync(dest, { recursive: true });
    if (!existsSync(join(dest, 'RULES.md'))) writeFileSync(join(dest, 'RULES.md'), PLACEHOLDER);
  } catch { /* an unwritable temp root is reported by the step, which can name itself */ }
}

// Copy this session's person's pack into `root`'s session pack root. Returns nothing a caller
// branches on: the directory is the answer, and the reasons a session gets no pack are a pure
// function of its config and environment. Throws only what the caller means to log.
export function copyUserPackToRepo({ root, config, env }) {
  const dest = packDirIn(root);
  try {
    const sessionRoot = join(root, '.claudinite', 'temp');
    mkdirSync(sessionRoot, { recursive: true });
    writeFileSync(join(sessionRoot, '.gitignore'), SESSION_ROOT_GITIGNORE);
  } catch { /* an unwritable temp root is reported by the step, which can name itself */ }
  const store = resolveStore(config);
  if (declineReason(config, env) !== null) return leavePlaceholder(dest);

  const packDir = packDirFor(store, env.CLAUDE_CODE_USER_EMAIL);
  let clone = null;
  let source = join(root, packDir);
  try {
    if (!existsSync(source)) {
      clone = checkout(store, packDir);
      source = join(clone, packDir);
    }
    if (!existsSync(source) || !statSync(source).isDirectory()) return leavePlaceholder(dest);

    const wanted = treeFiles(source).filter((p) => COPYABLE.test(p) && !p.split('/').includes('..'));
    if (!wanted.length || wanted.length > MAX_FILES) return leavePlaceholder(dest);

    // Empty the directory before writing. A pack left by an earlier session in this container,
    // for an earlier person or an earlier version of this one's, is content nobody here chose.
    // The root is the engine's session state and this pack's own subdirectory within it, so
    // nothing tracked is ever at risk.
    removeTree(dest);
    mkdirSync(dest, { recursive: true });

    let bytes = 0;
    let wroteManifest = false;
    for (const rel of wanted) {
      const content = readFileSync(join(source, rel));
      bytes += content.length;
      if (bytes > MAX_BYTES) { removeTree(dest); return leavePlaceholder(dest); }

      // Path-checked against the destination it claims to sit in.
      const target = join(dest, rel);
      const inside = relative(dest, target);
      if (inside.startsWith('..') || inside.startsWith(sep) || inside === '') continue;
      mkdirSync(dirname(target), { recursive: true });
      writeFileSync(target, content);
      if (rel === 'pack.mjs') wroteManifest = true;
    }
    if (!wroteManifest) writeFileSync(join(dest, 'pack.mjs'), SYNTHESIZED_MANIFEST);
    leavePlaceholder(dest); // a pack with no RULES.md of its own still needs the imported file
  } catch (e) {
    leavePlaceholder(dest);
    throw e;
  } finally {
    if (clone) { try { removeTree(clone); } catch { /* it outlives the session at worst */ } }
  }
}
import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { resolveStore, isUsableIdentity } from '../user_pack_address.mjs';

// A person's pack is addressed by their IDENTITY and nothing else: user_pack_address.mjs builds
// `<path>/<email>` from CLAUDE_CODE_USER_EMAIL, and session-prepare.mjs copies exactly that
// directory (locally when this tree is the store, over the network otherwise). There is no
// index, no registry and no fallback - a directory whose name is not a usable identity is
// simply never opened by anyone.
//
// And nothing says so. Every miss on the reading side is fail-soft on purpose: no identity,
// no store, no pack, a failed fetch - each is one note in the session context and the
// session carries on with default behavior. So a directory named `ariel`, or
// `Ariel@Gmail.com` for an identity the harness supplies in lower case, or a person's files
// parked loose in the store root, look perfectly fine in the tree and are dead. The person
// notices only by the absence of behavior they were expecting.
//
// THIS IS A PROPERTY OF BEING A STORE, not of any one fleet's store repo, which is why it
// sits here beside user_pack_address.mjs rather than in the store repo's own local pack: it imports the
// reader's `resolveStore`/`isUsableIdentity` as siblings, so the check can never be stricter
// or looser than the code that does the opening.
//
// ADVISORY, matching its sibling store-configured.mjs for the same reason: the loss is a
// nicety, no other check or task depends on it, and the fix is a rename.
//
// RELEVANCE-FIRST. It is inert unless this repo actually carries the store directory its own
// declaration names - which is every member of a fleet: they declare the pack to READ a store
// that lives somewhere else. Only the one repo that IS the store has anything to judge.
const PACK = 'claude-code-web-users-support';

const rule = {
  id: 'preferences-store-file-names',
  severity: 'advisory',
  description: 'Every entry in a personal-pack store this repo holds is README.md or an <identity>/ pack directory',
  doc: 'packs/claude-code-web-users-support/RULES.md',
  why: 'the reader copies a person\'s pack from <path>/<email>/ and fails soft on a miss, so a differently-named directory is never opened and nothing ever reports it',

  // `ctx.files` is the tracked, non-vendored set - the store is committed content, and an
  // uncommitted file is not published to the fleet yet anyway.
  run(ctx) {
    const store = resolveStore(ctx.config.packConfig?.[PACK] ?? null);
    if (!store) return []; // no usable store declared — store-configured reports that

    const prefix = `${store.path}/`;
    const held = (ctx.files ?? []).filter((f) => f.startsWith(prefix));
    if (!held.length) return []; // this repo is not the store, whatever it points at

    // One finding per top-level entry, not per file: a misnamed directory holding a whole
    // pack is one mistake with one fix, and a finding per file inside it would bury it.
    const seen = new Set();
    return held.flatMap((f) => {
      const rest = f.slice(prefix.length);
      const top = rest.includes('/') ? rest.slice(0, rest.indexOf('/')) : rest;
      if (seen.has(top)) return [];
      seen.add(top);
      if (!rest.includes('/')) {
        if (top === 'README.md') return []; // the store's own doc, deliberately not an identity
        return [finding(rule, {
          file: f,
          what: `sits loose in ${store.path}/ - a person's pack is only ever addressed as ${store.path}/<email>/`,
          fix: `move it into ${store.path}/<email>/, as that pack's RULES.md or one of its files, or out of the store entirely if it is not one person's pack`,
        })];
      }
      if (isUsableIdentity(top)) return [];
      return [finding(rule, {
        file: `${prefix}${top}`,
        what: `is not an identity the reader can address - it copies ${store.path}/<email>/ for the exact CLAUDE_CODE_USER_EMAIL the harness supplies`,
        fix: `rename it to that person's exact identity, case included, or move it out of ${store.path}/`,
      })];
    });
  },
};

export default rule;
// This pack's session-start step: say what the person's pack cost, or why they have none.
//
// THE COPY ITSELF IS session-prepare.mjs, which runs in the phase before the skill mount and
// the self-test, because what it writes is a pack those steps have to see. By the time this
// step runs, the person's rules are already in the session on the memory channel (the rules
// index imports the copied pack's prose) and their skills are already mounted. What is left
// is the part only a reader needs.
//
// SO IT EMITS NO RULES. Prose on this channel is prose the harness may truncate on the way in,
// with nothing on either side able to tell (#807), which is exactly why the pack rides the
// memory channel instead. A step that also printed the rules would spend the session's context
// twice for one set of them.
//
// AND IT READS NO STATUS FILE. The directory is the answer: the placeholder means nothing
// landed, and why is a pure function of the config and the environment.

import { existsSync, readFileSync } from 'node:fs';
import { PLACEHOLDER, proseIn } from './copy_user_pack_to_repo.mjs';
import { resolveStore, declineReason } from './user_pack_address.mjs';

const note = (s) => { process.stdout.write(`PERSONAL PACK: ${s} - proceeding with default interaction behavior.\n`); process.exit(0); };

const root = process.env.CLAUDE_PROJECT_DIR || process.cwd();
const config = (() => {
  try { return JSON.parse(process.env.CLAUDINITE_PACK_CONFIG || '{}'); } catch { return {}; }
})();

const prose = existsSync(proseIn(root)) ? readFileSync(proseIn(root), 'utf8') : null;

// No file at all means the prepare phase never ran: an engine older than the phase, which a
// member holds until the engine lane catches up with the pack lane. Nothing to report about
// this person, and nothing this step can do about it from here.
if (prose === null) {
  note('this repo\'s engine has no session-prepare phase, so no personal pack was copied in');
}

if (prose === PLACEHOLDER) {
  const why = declineReason(config, process.env)
    ?? `${resolveStore(config).repo} holds no pack for this person, or it could not be read`;
  note(why);
}

// AND IT WEIGHS NOTHING. The copy is on disk before the summary step runs, off the same
// registry the summary reads every other pack from, so the summary counts this pack with the
// rest and one number covers the whole load. A figure emitted here would be that same prose
// stated twice under two names, and a reader holding only the corpus figure would be told a
// corpus smaller than the one they have.
process.exit(0);
CLAUDE_CODE_ACCOUNT_UUID=<set>
CLAUDE_CODE_USER_EMAIL=<set>
GH_TOKEN=<set>
GITHUB_TOKEN=<set>
CLAUDE_CODE_ORGANIZATION_UUID=<set>

