import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { resolveStore, isUsableIdentity } from '../user_pack_address.mjs';
// A namespace import, guarded in `run`: the pack and engine lanes deliver on separate
// cadences, and a member whose engine predates the helper must load this pack rather
// than fault on a missing named export.
import * as provenance from '../../../engine/checks/helpers/provenance.mjs';

// A person's pack is a pack (the provenance design, #2136): each rule in it is an element,
// and its file sits where every other pack keeps them, in the pack's own `provenance/`.
// This check asserts existence only - every rule bullet ends with a marker naming a file
// under that folder - and shares no logic with the growth pack beyond the engine's own
// bullet reader: the grammar of the file is judged by the growth tool's `check`, run by the
// session that edits the rule.
//
// ADVISORY, like everything in this pack: the loss is a missing why for a rule, never a
// broken repo. RELEVANCE-FIRST like its siblings: inert unless this repo IS the store -
// only the one repo that holds `<path>/<email>/` packs has anything to judge.
const PACK = 'claude-code-web-users-support';

// @deprecated The sidecar folder a person's provenance sat in while the store was flat and
// could hold nothing but `<email>.md`. Nothing here calls it and no layout has it any more; it
// stays only because a member's own local pack may have imported it, and the pack and engine
// lanes deliver on separate cadences.
// @legacy-tolerance advisory:none retire:#2188
export const provenanceDirOf = (store) => `${store.path}-provenance`;


const rule = {
  id: 'preferences-provenance',
  severity: 'advisory',
  description: 'Every rule in a personal pack this repo stores ends with a marker naming its provenance file in that pack',
  doc: 'packs/claude-code-web-users-support/RULES.md',
  why: 'a rule with no file has no record of when it was set or what prompted it, and the session that changes it next is the only reader who could have written that down',

  run(ctx) {
    if (typeof provenance.ruleBlocks !== 'function') return []; // an engine that predates the helper
    const { ruleBlocks } = provenance;
    const store = resolveStore(ctx.config.packConfig?.[PACK] ?? null);
    if (!store) return [];
    const prefix = `${store.path}/`;
    // One prose file per person, at the pack's own `RULES.md` - the only file in a person's
    // directory this check has anything to say about.
    const held = (ctx.files ?? []).filter((f) => {
      const rest = f.startsWith(prefix) ? f.slice(prefix.length) : null;
      return rest !== null && rest.endsWith('/RULES.md') && rest.split('/').length === 2;
    });
    if (!held.length) return [];
    const out = [];
    for (const file of held) {
      const email = file.slice(prefix.length, -'/RULES.md'.length);
      if (!isUsableIdentity(email)) continue; // store-file-names reports the name
      const dir = `${prefix}${email}/provenance`;
      for (const b of ruleBlocks(ctx.read(file) ?? '')) {
        if (!b.slug) {
          out.push(finding(rule, {
            file, line: b.start + 1,
            what: `the rule "${b.trigger}" ends with no marker naming its provenance file`,
            fix: `end it with a slug marker, e.g. (${b.trigger.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').split('-').slice(0, 3).join('-')}), and write that file under ${dir}/ with a born entry saying when the rule was set and what prompted it`,
          }));
        } else if (!ctx.exists(`${dir}/${b.slug}.md`)) {
          out.push(finding(rule, {
            file, line: b.lastLine + 1,
            what: `the rule "${b.trigger}" names ${dir}/${b.slug}.md, which does not exist`,
            fix: `create ${dir}/${b.slug}.md with a born entry, or fix the marker to the file it meant`,
          }));
        }
      }
    }
    return out;
  },
};

export default rule;
import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { resolveStore } from '../user_pack_address.mjs';

// Declaring this pack is a statement that this project's users HAVE a preferences
// store. If its entry names none — or names one that does not resolve — the pack is
// wired up and silently inert: every session reads its fail-soft note instead of
// anyone's preferences, and nothing else ever says so.
//
// ADVISORY, not blocking. The failure is a lost nicety, never a broken repo: no
// check, no task and no other pack depends on the store being reachable, and a
// project mid-adoption (declared, interview not yet answered) is in exactly this
// state legitimately for a while. It is a nudge with the fix in it.
const rule = {
  id: 'preferences-store-configured',
  severity: 'advisory',
  description: 'A declared claude-code-web-users-support pack names a store its session-start step can read',
  doc: 'packs/claude-code-web-users-support/RULES.md',
  why: 'a declared pack with no store injects nobody\'s preferences and says so only in a fail-soft note nobody reads twice',

  run(ctx) {
    // The pack's own entry config, through the engine's normalized per-pack view.
    const config = ctx.config.packConfig?.['claude-code-web-users-support'];
    if (resolveStore(config ?? null)) return [];
    return [finding(rule, {
      file: '.claudinite-settings.json',
      what: config === undefined
        ? 'the claude-code-web-users-support pack is declared but names no store'
        : `the claude-code-web-users-support pack's store does not resolve (${JSON.stringify(config)})`,
      fix: 'give the pack entry a "config": { "repo": "owner/name" } naming the repo that holds this project\'s users\' preferences — "path" is optional and defaults to preferences/',
    })];
  },
};

export default rule;
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, mkdirSync, writeFileSync, existsSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { removeTree } from '../../../engine/remove-tree.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const PREPARE = join(here, '..', 'session-prepare.mjs');
const START = join(here, '..', 'session-start.mjs');
const COPIED = join('.claudinite', 'temp', 'packs', 'current_user');

// The pack's two steps, run exactly as the engine runs them: subprocesses, handed the pack's
// own entry config in CLAUDINITE_PACK_CONFIG and the session's identity in
// CLAUDE_CODE_USER_EMAIL. Most of what follows is one of the ways the copy can miss, because
// every one of them must be fail-soft: the pack contributes a nicety, and a nicety that can
// stop a session from starting is a defect, not a feature.
//
// Attendedness is one of those inputs, so every case states the one it means and none inherits
// the ambient value: the harness exports CLAUDE_CODE_SESSION_ATTENDED=0 in exactly the sessions
// the task queue runs in, so a case that let it through would assert about the session the
// suite happens to run in rather than the one it describes, green at a terminal and in CI and
// red for every unattended run. `attended: null` is the older harness that sets nothing at all.
const { CLAUDE_CODE_SESSION_ATTENDED: _ambientAttended, ...BASE_ENV } = process.env;

const run = (step, project, { email = 'me@example.com', config = {}, attended = '1', ...extra } = {}) => spawnSync('node', [step], {
  encoding: 'utf8',
  env: {
    ...BASE_ENV,
    CLAUDE_PROJECT_DIR: project,
    CLAUDE_CODE_USER_EMAIL: email,
    CLAUDINITE_PACK_CONFIG: JSON.stringify(config),
    // An unreachable store, so a case that reaches the clone path fails there rather than
    // going to the network from a test.
    CLAUDINITE_USER_PACKS_CLONE_URL: join(tmpdir(), 'claudinite-no-such-store'),
    ...extra,
    ...(attended === null ? {} : { CLAUDE_CODE_SESSION_ATTENDED: attended }),
  },
});

const project = () => mkdtempSync(join(tmpdir(), 'claudinite-personal-'));
const copied = (root, rel) => readFileSync(join(root, COPIED, rel), 'utf8');
const STORE = { repo: 'owner/store' };

// A store this tree holds, so the copy takes its local-first branch.
function storeHere(root, files, { path = 'preferences', email = 'me@example.com' } = {}) {
  for (const [rel, body] of Object.entries(files)) {
    const target = join(root, path, email, rel);
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, body);
  }
}

test('the whole pack is copied, not only its prose', () => {
  // The point of the shape: a person brings skills and checks, not just rules, and the engine
  // loads them because what landed is an ordinary pack directory.
  const root = project();
  try {
    storeHere(root, {
      'RULES.md': '# Mine\n\n- **Ending a turn** - a callout. (ending-turn)\n',
      'skills/pep-talk/SKILL.md': '---\nname: pep-talk\ndescription: Encourage.\n---\nBe kind.\n',
      'worldRules/mine.mjs': 'export default { id: "mine", run: () => [] };\n',
      'provenance/ending-turn.md': '# ending-turn\n',
    });
    assert.equal(run(PREPARE, root, { config: STORE }).status, 0);

    assert.match(copied(root, 'RULES.md'), /Ending a turn/);
    assert.match(copied(root, 'skills/pep-talk/SKILL.md'), /Be kind/);
    assert.match(copied(root, 'worldRules/mine.mjs'), /id: "mine"/);
    assert.match(copied(root, 'provenance/ending-turn.md'), /ending-turn/);
    // A person with rules to state should not have to write a manifest to state them, and the
    // manifest written for them must claim neither the id nor a version.
    assert.match(copied(root, 'pack.mjs'), /ruleRoutingGuidance/);
    assert.doesNotMatch(copied(root, 'pack.mjs'), /\bid:|\bversion:/);
  } finally { removeTree(root); }
});

test('a pack that carries its own manifest keeps it', () => {
  const root = project();
  try {
    storeHere(root, { 'RULES.md': 'x\n', 'pack.mjs': 'export default { ruleRoutingGuidance: { belongs: "MINE" } };\n' });
    run(PREPARE, root, { config: STORE });
    assert.match(copied(root, 'pack.mjs'), /MINE/);
  } finally { removeTree(root); }
});

test('the store is read locally when this tree IS the store', () => {
  // The working copy wins: in the store repo itself, a clone would serve the default branch and
  // quietly hide the edit the owner is making right now.
  const root = project();
  try {
    storeHere(root, { 'RULES.md': 'MY RULES\n' });
    assert.equal(run(PREPARE, root, { config: STORE }).status, 0);
    assert.match(copied(root, 'RULES.md'), /MY RULES/);
  } finally { removeTree(root); }
});

test('a declared path is honoured, not just the default', () => {
  const root = project();
  try {
    storeHere(root, { 'RULES.md': 'ELSEWHERE\n' }, { path: 'team/people' });
    run(PREPARE, root, { config: { ...STORE, path: 'team/people' } });
    assert.match(copied(root, 'RULES.md'), /ELSEWHERE/);
  } finally { removeTree(root); }
});

test('nothing copied still leaves a pack the engine can load', () => {
  // The rules index imports the copied prose by a literal path in every session of a repo that
  // declares this pack, so the file has to be there even when nobody's pack is.
  const root = project();
  try {
    const r = run(PREPARE, root, { email: 'nobody@example.com', config: STORE });
    assert.equal(r.status, 0);
    assert.match(copied(root, 'RULES.md'), /No personal pack/);
  } finally { removeTree(root); }
});

test('what a session copies in never shows up as a change to commit', () => {
  // The member's own .gitignore may say nothing about the session root, so the root has to
  // ignore itself, on the copy path and on the placeholder path alike.
  for (const email of ['me@example.com', 'nobody@example.com']) {
    const root = project();
    try {
      assert.equal(spawnSync('git', ['init', '-q', root]).status, 0);
      storeHere(root, { 'RULES.md': 'x\n' });
      assert.equal(run(PREPARE, root, { email, config: STORE }).status, 0);
      assert.ok(existsSync(join(root, COPIED, 'RULES.md')));
      const status = spawnSync('git', ['status', '--porcelain', '--untracked-files=all'], { cwd: root, encoding: 'utf8' });
      assert.doesNotMatch(status.stdout, /\.claudinite/, email);
    } finally { removeTree(root); }
  }
});

test('every miss is a soft note from the start step, never a halt', () => {
  const root = project();
  try {
    run(PREPARE, root, { email: 'nobody@example.com', config: STORE });
    const r = run(START, root, { email: 'nobody@example.com', config: STORE });
    assert.equal(r.status, 0);
    assert.match(r.stdout, /owner\/store holds no pack for this person/);
    assert.match(r.stdout, /default interaction behavior/);
    assert.doesNotMatch(r.stdout, /STOP|AskUserQuestion/);              // fail-soft, no halt-gate
    assert.doesNotMatch(r.stdout, /hookSpecificOutput|additionalContext/); // plain text, no JSON envelope
