// Copy this session's person's pack into `root`'s session pack root. `identity` is what
// read_github_login.mjs answered, `{ login }` or `{ error }`. Returns nothing a caller branches
// on: the directory and the address record are the answer. Throws only what the caller means
// to log.
export function copyUserPackToRepo({ root, config, env, identity = {} }) {
  const dest = packDirIn(root);
  try {
    const sessionRoot = join(root, '.claudinite', 'temp');
    mkdirSync(sessionRoot, { recursive: true });
    writeFileSync(join(sessionRoot, '.gitignore'), SESSION_ROOT_GITIGNORE);
  } catch { /* an unwritable temp root is reported by the step, which can name itself */ }
  const store = resolveStore(config);
  const record = { login: identity.login ?? null, loginError: identity.error ?? null, email: env.CLAUDE_CODE_USER_EMAIL || null, tried: [], used: null, form: null };
  const writeRecord = () => {
    try { writeFileSync(addressRecordIn(root), `${JSON.stringify(record, null, 2)}\n`); } catch { /* the note then says less */ }
  };
  if (declineReason(config, env) !== null) { writeRecord(); return leavePlaceholder(dest); }

  const candidates = candidateDirs(store, { login: identity.login, email: env.CLAUDE_CODE_USER_EMAIL });
  record.tried = candidates.map((c) => c.dir);
  if (!candidates.length) { writeRecord(); return leavePlaceholder(dest); }

  let clone = null;
  let source = null;
  try {
    let found = candidates.find((c) => isDir(join(root, c.dir)));
    if (found) {
      source = join(root, found.dir);
    } else {
      clone = checkout(store, record.tried);
      found = candidates.find((c) => isDir(join(clone, c.dir)));
      if (found) source = join(clone, found.dir);
    }
    if (!found) return leavePlaceholder(dest);
    record.used = found.dir;
    record.form = found.form;

