1	// This pack's session-start step: say what the person's pack cost, or why they have none.
2	//
3	// THE COPY ITSELF IS session-prepare.mjs, which runs in the phase before the skill mount and
4	// the self-test, because what it writes is a pack those steps have to see. By the time this
5	// step runs, the person's rules are already in the session on the memory channel (the rules
6	// index imports the copied pack's prose) and their skills are already mounted. What is left
7	// is the part only a reader needs.
8	//
9	// SO IT EMITS NO RULES. Prose on this channel is prose the harness may truncate on the way in,
10	// with nothing on either side able to tell (#807), which is exactly why the pack rides the
11	// memory channel instead. A step that also printed the rules would spend the session's context
12	// twice for one set of them.
13	//
14	// AND IT READS NO STATUS FILE. The directory is the answer: the placeholder means nothing
15	// landed, and why is a pure function of the config and the environment.
16	
17	import { existsSync, readFileSync } from 'node:fs';
18	import { PLACEHOLDER, proseIn } from './copy_user_pack_to_repo.mjs';
19	import { resolveStore, declineReason } from './user_pack_address.mjs';
20	
21	const note = (s) => { process.stdout.write(`PERSONAL PACK: ${s} - proceeding with default interaction behavior.\n`); process.exit(0); };
22	
23	const root = process.env.CLAUDE_PROJECT_DIR || process.cwd();
24	const config = (() => {
25	  try { return JSON.parse(process.env.CLAUDINITE_PACK_CONFIG || '{}'); } catch { return {}; }
26	})();
27	
28	const prose = existsSync(proseIn(root)) ? readFileSync(proseIn(root), 'utf8') : null;
29	
30	// No file at all means the prepare phase never ran: an engine older than the phase, which a
31	// member holds until the engine lane catches up with the pack lane. Nothing to report about
32	// this person, and nothing this step can do about it from here.
33	if (prose === null) {
34	  note('this repo\'s engine has no session-prepare phase, so no personal pack was copied in');
35	}
36	
37	if (prose === PLACEHOLDER) {
38	  const why = declineReason(config, process.env)
39	    ?? `${resolveStore(config).repo} holds no pack for this person, or it could not be read`;
40	  note(why);
41	}
42	
43	// AND IT WEIGHS NOTHING. The copy is on disk before the summary step runs, off the same
44	// registry the summary reads every other pack from, so the summary counts this pack with the
45	// rest and one number covers the whole load. A figure emitted here would be that same prose
46	// stated twice under two names, and a reader holding only the corpus figure would be told a
47	// corpus smaller than the one they have.
48	process.exit(0);

2	// anything reads the session's pack set.
3	//
4	// WHY PREPARE AND NOT START. The skill mount and the self-test read that set before
5	// session-start.mjs runs. A pack arriving after them is a pack whose skills are not mounted
6	// and whose absence was never judged, so the copy has to happen in the phase that runs first
7	// (engine/pack_loader/run-pack-session-start.mjs).
8	//
9	// IT SAYS NOTHING HERE. A prepare step's stdout is a diagnostic, not session context; what
10	// landed is the directory it wrote, which session-start.mjs reads to write the one note a
11	// person sees.
12	
13	import { copyUserPackToRepo } from './copy_user_pack_to_repo.mjs';
14	
15	const config = (() => {
16	  try { return JSON.parse(process.env.CLAUDINITE_PACK_CONFIG || '{}'); } catch { return {}; }
17	})();
18	
